import type { Book, BookCategory } from '@/features/library/types';

/**
 * Library seed for the development mock.
 *
 * Titles and categories only — the physical copies and the loans are
 * generated by `devApi` from the live student and teacher rosters, because a
 * loan hard-coded against a member id would break the moment the seed moved.
 *
 * Deliberately uneven: one title with a single copy, one with none at all,
 * one retired category, and one book priced low enough that the fine cap
 * actually bites. Every branch of the availability column, the fine ceiling
 * and the "no copies yet" empty state is reachable without editing anything.
 */

interface CategorySeed {
  name: string;
  code: string;
  description: string | null;
  isActive?: boolean;
}

const CATEGORY_SEED: CategorySeed[] = [
  { name: 'Fiction', code: 'FIC', description: 'Novels, short stories and drama.' },
  { name: 'Science', code: 'SCI', description: 'Physics, chemistry, biology and general science.' },
  { name: 'Mathematics', code: 'MAT', description: 'Textbooks, problem sets and reference.' },
  { name: 'History', code: 'HIS', description: 'Indian and world history.' },
  { name: 'Biography', code: 'BIO', description: 'Lives and memoirs.' },
  { name: 'Reference', code: 'REF', description: 'Dictionaries, atlases and encyclopaedias.' },
  { name: 'Children', code: 'CHD', description: 'Picture books and early readers.' },
  // Retired: still holds its books, but takes no new ones.
  { name: 'Periodicals', code: 'PER', description: 'Bound magazine volumes.', isActive: false },
];

export const categories: BookCategory[] = CATEGORY_SEED.map((seed, index) => ({
  id: index + 1,
  name: seed.name,
  code: seed.code,
  description: seed.description,
  is_active: seed.isActive ?? true,
  // Filled in by the mock from the live book list.
  books_count: 0,
  created_at: '2025-04-01T00:00:00.000000Z',
}));

