/** How many copies the mock should mint for each title. */
export const seededCopyCounts: Record<number, number> = {};

export const books: Book[] = BOOK_SEED.map((seed, index) => {
  const id = index + 1;
  const category =
    categories.find((entry) => entry.code === seed.categoryCode) ?? categories[0];

  seededCopyCounts[id] = seed.copies;

  return {
    id,
    title: seed.title,
    subtitle: seed.subtitle ?? null,
    author: seed.author,
    isbn: seed.isbn,
    category_id: category.id,
    category_name: category.name,
    publisher: seed.publisher,
    edition: seed.edition,
    publication_year: seed.year,
    language: seed.language ?? 'English',
    pages: seed.pages,
    price: seed.price,
    shelf_no: seed.shelf,
    description: seed.description ?? null,
    // All three computed by the mock from the copies it mints.
    total_copies: 0,
    available_copies: 0,
    issued_copies: 0,
    created_at: '2025-04-01T00:00:00.000000Z',
    updated_at: '2025-06-01T00:00:00.000000Z',
  };
});

export const nextBookId = books.length + 1;
export const nextCategoryId = categories.length + 1;
